69	// object, region options plus object options.
70	inline bool object_setting(const std::string& key)
71	{
72	    static const PrintRegionConfig region;
73	    static const PrintObjectConfig object;
74	    return region.optptr(key) != nullptr || object.optptr(key) != nullptr;
