95	// Orca's scalar deserializers accept a numeric prefix (e.g. "4bad"). Check
96	// complete consumption before calling the authoritative parser, so malformed
97	// input cannot silently become a different approved value.
98	inline bool complete_setting_number(const std::string& text, ConfigOptionType type)
99	{
100	    if (type != coFloat && type != coInt && type != coPercent) return true;
101	    std::istringstream input(text);
102	    input.imbue(std::locale::classic());
103	    double number;
104	    if (!(input >> number) || !std::isfinite(number)) return false;
105	    input >> std::ws;
106	    if (type == coPercent && input.peek() == '%') { input.get(); input >> std::ws; }
107	    if (!input.eof()) return false;
108	    if (type == coInt) {
109	        std::istringstream integer_input(text);
110	        int integer;
111	        if (!(integer_input >> integer)) return false;
112	        integer_input >> std::ws;
113	        return integer_input.eof();
114	    }
115	    return true;
116	}
