118	// Parses one value into `config` the way a patch does, with the setting's
119	// own bounds; the result says why a value was refused.
120	inline std::optional<std::string> set_setting_value(DynamicPrintConfig& config, const std::string& key, const std::string& text)
121	{
122	    const ConfigOptionDef* definition = print_config_def.get(key);
123	    if (!complete_setting_number(text, definition->type))
124	        return "Expected a complete finite " + setting_type(definition->type) + " value.";
125	    try {
126	        config.set_deserialize_strict(key, text);
127	    } catch (const BadOptionValueException& error) {
128	        return std::string(error.what());
129	    }
130	    const ConfigOption* option = config.option(key);
131	    // Bounds by type: a boolean has none, and reading one as a float is
132	    // undefined behaviour.
133	    if (definition->type == coEnum)
134	        return definition->has_enum_value(option->serialize()) ? std::nullopt : std::optional<std::string>("Value is not in the allowed enum values.");
135	    const bool numeric = definition->type == coInt || definition->type == coFloat || definition->type == coPercent ||
136	                         definition->type == coFloatOrPercent;
137	    if (numeric && !definition->is_value_valid(definition->type == coInt ? static_cast<double>(config.opt_int(key)) :
138	                                                                           static_cast<const ConfigOptionFloat*>(option)->value))
139	        return std::string("Value is outside the setting's bounds.");
140	    return std::nullopt;
141	}
