143	// Audit against ConfigManipulation::update_print_fff_config. These are every
144	// active modal predicate, including unrelated pre-existing invalid values:
145	// update() evaluates the entire config after any allowed batch. Keep refusal
146	// here; the live normalizer remains unchanged and owns its UI behavior.
147	inline void check_process_dialogs(const DynamicPrintConfig& config, SettingsPreview& result)
148	{
149	    const auto block = [&](bool condition, const std::string& key, const std::string& message) {
150	        if (condition) result.issues.push_back({key, "incompatible_settings", message});
151	    };
152	    const double height = config.opt_float("layer_height");
153	    const auto& printer = wxGetApp().preset_bundle->printers.get_edited_preset().config;
154	    const double maximum = printer.opt_float("max_layer_height", 0);
155	    if (height < EPSILON)
156	        result.issues.push_back({"layer_height", "invalid_setting_value", "Layer height is below Orca's minimum.", {}, {}, EPSILON, {}});
157	    if (maximum > 0.2 && height > maximum + EPSILON)
158	        result.issues.push_back({"layer_height", "invalid_setting_value", "Layer height exceeds the printer maximum.", {}, {}, {}, maximum});
159	    for (const auto* key : {"ironing_spacing", "support_ironing_spacing"})
160	        block(config.opt_float(key) < 0.05, key, "Ironing spacing would open Orca's correction dialog; correct it first.");
161	    block(config.opt_float("initial_layer_print_height") < EPSILON, "initial_layer_print_height", "Initial layer height would open Orca's correction dialog.");
162	    for (const auto* key : {"xy_hole_compensation", "xy_contour_compensation"})
163	        block(std::abs(config.opt_float(key)) > 2, key, "XY compensation would open Orca's correction dialog.");
164	    block(config.opt_float("elefant_foot_compensation") > 1, "elefant_foot_compensation", "Elephant foot compensation would open Orca's correction dialog.");
165	    block(config.opt_bool("spiral_mode") && !(config.opt_int("wall_loops") == 1 && config.opt_int("top_shell_layers") == 0 &&
166	        config.option<ConfigOptionPercent>("sparse_infill_density")->value == 0 && !config.opt_bool("enable_support") &&
167	        config.opt_int("enforce_support_layers") == 0 && !config.opt_bool("detect_thin_wall") && !config.opt_bool("overhang_reverse") &&
168	        config.opt_enum<TimelapseType>("timelapse_type") == tlTraditional && !config.opt_bool("enable_wrapping_detection")),
169	        "spiral_mode", "Spiral mode conflicts with wall_loops, top_shell_layers, infill, support, thin walls, overhang reversal, timelapse, or wrapping detection.");
170	    block(config.opt_bool("alternate_extra_wall") && config.opt_enum<EnsureVerticalShellThickness>("ensure_vertical_shell_thickness") == evstAll,
171	        "alternate_extra_wall", "Alternate extra wall conflicts with ensure_vertical_shell_thickness=all.");
172	    block(config.opt_enum<SeamScarfType>("seam_slope_type") != SeamScarfType::None && config.get_abs_value("seam_slope_start_height") >= height,
173	        "layer_height", "Layer height conflicts with seam_slope_type and seam_slope_start_height; scarf start height must be below layer height.");
174	    block(config.opt_float("infill_lock_depth") > config.opt_float("skin_infill_depth"), "infill_lock_depth", "Infill lock depth exceeds skin_infill_depth.");
175	    block(config.opt_enum<FuzzySkinMode>("fuzzy_skin_mode") != FuzzySkinMode::Displacement &&
176	        config.opt_enum<PerimeterGeneratorType>("wall_generator") != PerimeterGeneratorType::Arachne,
177	        "fuzzy_skin_mode", "This fuzzy skin mode requires wall_generator=arachne.");
178	}
