180	// ConfigManipulation resets support_style to default, silently, when it does
181	// not fit the support type. A patch that would be rewritten that way is
182	// refused with the styles that fit, rather than approved and then changed.
183	inline void check_support_style(const DynamicPrintConfig& config, const std::map<std::string, std::string>& patch,
184	                                SettingsPreview& result)
185	{
186	    if (!config.opt_bool("enable_support") ||
187	        (!patch.count("support_style") && !patch.count("support_type") && !patch.count("enable_support")))
188	        return;
189	    const bool tree = is_tree(config.opt_enum<SupportType>("support_type"));
190	    const std::vector<SupportMaterialStyle> fitting = tree ?
191	        std::vector<SupportMaterialStyle>{smsDefault, smsTreeSlim, smsTreeStrong, smsTreeHybrid, smsTreeOrganic} :
192	        std::vector<SupportMaterialStyle>{smsDefault, smsGrid, smsSnug};
193	    const auto style = config.opt_enum<SupportMaterialStyle>("support_style");
194	    if (std::find(fitting.begin(), fitting.end(), style) != fitting.end())
195	        return;
196	    std::vector<std::string> allowed;
197	    for (SupportMaterialStyle candidate : fitting)
198	        allowed.push_back(ConfigOptionEnum<SupportMaterialStyle>(candidate).serialize());
199	    result.issues.push_back({"support_style", "invalid_setting_value",
200	                             std::string("With ") + (tree ? "tree" : "normal") +
201	                                 " supports, support_style must be one of the allowed values; OrcaSlicer would reset it to default.",
202	                             allowed});
203	}
204	
205	inline bool process_tab_toggles_options(Tab& tab)
206	{
207	    // Public field lookup identifies the active page without adding an Orca
208	    // accessor. TabPrint::update skips toggles on an absent/Dependencies page.
209	    for (const auto& key : Preset::print_options()) {
210	        if (tab.get_field(key)) {
211	            Page* page = nullptr;
212	            tab.get_field(key, &page);
213	            return page && page->title() != "Dependencies";
214	        }
215	    }
216	    return false;
217	}
218	
219	inline void predict_process_normalization(DynamicPrintConfig& config)
220	{
221	    // The modal predicates above were checked first. Execute Orca's own
222	    // normalization on the clone with no presentation callbacks; don't keep
223	    // a duplicate table of dependent values or infill-pattern capabilities.
224	    ConfigManipulation normalizer([] {}, [](const std::string&, bool, int) {}, {}, {});
225	    auto& bundle = *wxGetApp().preset_bundle;
226	    const auto& selected = bundle.prints.get_selected_preset();
227	    normalizer.initialize_support_material_overhangs_queried(!selected.is_system && !selected.is_dirty &&
228	        config.opt_bool("enable_support") && !config.opt_bool("detect_overhang_wall"));
229	    normalizer.set_is_BBL_Printer(bundle.is_bbl_vendor());
230	    normalizer.update_print_fff_config(&config, true, false);
231	    if (process_tab_toggles_options(*wxGetApp().get_tab(Preset::TYPE_PRINT)))
232	        normalizer.toggle_print_fff_options(&config, true);
233	}
