#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI { class Plater; }

namespace Slic3r::GUI::JusPrin::SetupCommands {

struct PrinterInfo
{
    std::string preset_name;
    wxString    nickname;        // a named printer's name, else printer_model, else the label without " nozzle"
    double      nozzle{0.};      // the first nozzle
    // Every nozzle, in extruder order. One entry on a single-nozzle printer.
    std::vector<double> nozzles;
    std::size_t extruder_count{1};
    bool        valid{false};
};

struct FilamentInfo
{
    std::string preset_name;
    wxString    alias;           // the short name: display name, "@printer" suffix removed
    // The filament's brand -- "Bambu Lab", "eSUN", "Generic" -- read from the
    // preset's own filament_vendor option. Not Preset::vendor, which names the
    // profile bundle the preset shipped in ("BBL", "OrcaFilamentLibrary") and
    // so can never identify an unbranded preset. Empty when the preset
    // declares no vendor.
    wxString    vendor;
    wxString    material;        // filament_type[0], e.g. "PLA"
    bool        valid{false};
};

// One of the project's numbered filament entries: one filament, one colour.
struct FilamentSlot
{
    std::size_t  index{0};       // 0-based; the person reads index + 1
    FilamentInfo filament;
    wxString     colour;         // "#RRGGBB", or empty
    // Whether the current plate prints with this slot, as Orca's own plate
    // reports it from the model -- before slicing, too.
    bool         used{false};
    // The nozzle this slot feeds, on a printer with nozzles of more than one
    // size; zero otherwise.
    double       nozzle{0.};
};

// -- Reads ------------------------------------------------------------------

PrinterInfo  current_printer();
FilamentInfo current_filament();          // slot 1
// Slot 1's colour as "#RRGGBB", or empty.
wxString     current_colour();

// Every filament slot in the project, in slot order.
#include <algorithm>
#include <cmath>
#include <functional>
#include <map>
#include <set>

namespace Slic3r::GUI::JusPrin::SetupCommands {

namespace {

// The alias Orca shows in the sidebar: the preset's alias, with the
// "@<printer>" qualifier trimmed the way StatusRow already trims it.
wxString display_alias(const Preset& preset)
{
    wxString alias = wxString::FromUTF8(preset.alias.empty() ? preset.name : preset.alias);
    alias = alias.BeforeFirst('@');
    alias.Trim();
    return alias;
}

wxString option_string(const DynamicPrintConfig& config, const char* key, unsigned index = 0)
{
    if (const auto* option = config.option<ConfigOptionStrings>(key); option && option->values.size() > index)
        return wxString::FromUTF8(option->values[index]);
    return {};
}

// The brand printed on the reel. Orca resolves filament_vendor through the
// inheritance chain, so a branded profile reports its own name and everything
// that only inherits fdm_filament_common reports "Generic". Preset::vendor
// cannot answer this: it names the profile bundle the preset shipped in.
wxString filament_vendor(const Preset& preset)
{
    const wxString vendor = option_string(preset.config, "filament_vendor");
    // PrintConfig's stand-in for a preset that declares no vendor at all. It is
    // a placeholder, not a brand, so it reads here as no vendor.
    return vendor == "(Undefined)" ? wxString{} : vendor;
}

FilamentInfo filament_info(const Preset& preset)
{
    FilamentInfo info;
    info.preset_name = preset.name;
    info.alias       = display_alias(preset);
    info.vendor      = filament_vendor(preset);
    info.material    = option_string(preset.config, "filament_type");
    info.valid       = true;
    return info;
}

// The nozzle each slot feeds. Orca's filament_map names an extruder per slot

