// -- The panel's own page --------------------------------------------------

bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
{
    if (type == "printer_instructions") {
        // Bounded: the page's words become every request's system prompt.
        const std::string text = payload.value("text", std::string());
        if (text.size() <= kInstructionsLimit && text != m_instructions) {
            m_instructions = text;
            m_host.profile_changed();
        }
        return true;
    }
    if (type == "printer_opening") {
        // The first line is the page's to write and the app's to post, once:
        // a reloaded page asks again, and the thread already has it.
        const std::string text = payload.value("text", std::string());
        if (m_opened || text.empty() || text.size() > kNoteLimit)
            return true;
        m_opened                     = true;
        const std::string message_id = m_host.post_opening(text);
        for (json& entry : m_blocks)
            if (entry.value("afterMessageId", std::string()).empty())
                entry["afterMessageId"] = message_id;
        m_host.session_changed();
        return true;
    }
    if (type != "printer_action")
        return false;

    const std::string action = payload.value("action", std::string());
    if (action == "close")
        m_host.close_panel();
    else if (action == "manual_setup") {
        // The overflow menu's way to OrcaSlicer's own printer list; what it
        // added is news the model answers.
        const ManualPrinterResult result = m_backend.run_manual_setup();
        if (!result.added.empty()) {
            m_printer_name = result.added.front().name;
    json physical_prints = json::array();
    for (const PhysicalPrintRecord& record : document.physical_prints())
        physical_prints.push_back(physical_print_json(record));
    json changes = json::array();
    for (const ChangeEntry& change : document.changes())
        changes.push_back(change_json(change));

    json payload{{"agent", json{{"status", availability_name(m_availability)}}},
                 {"appearance", m_dark ? "dark" : "light"},
                 {"conversations", std::move(conversations)},
                 {"activeConversationId", active},
                 {"conversation", std::move(conversation)},
                 {"streamingMessageId", m_stream ? json(m_stream->message.id) : json(nullptr)},
                 {"conversationBusy", m_stream.has_value() || !m_tool_continuations.empty()},
                 {"toolActivities", std::move(tool_activities)},
                 {"draft", m_persistence.draft()},
                 {"attachments", std::move(attachments)},
                 {"builds", std::move(builds)},
                 {"exportedCopies", std::move(exported_copies)},
                 {"physicalPrints", std::move(physical_prints)},
                 {"changes", std::move(changes)},
                 {"context", context_json(snapshot, agent_authored_keys(snapshot),
                                          m_persistence.document().setup_intent(active))}};
    if (m_session_state_provider)
        payload["session"] = m_session_state_provider();
    if (m_navigation_state_provider)
        payload["navigation"] = m_navigation_state_provider();
    send_envelope(Protocol::kState, payload.dump(), correlation_id);
}

void AgentHost::send_context()
{
    const WorkspaceSnapshot snapshot = m_workspace.snapshot();
    m_last_session  = snapshot.session.value();
    m_last_revision = snapshot.revision;
    send_envelope(Protocol::kContext,
                  json{{"context", context_json(snapshot, agent_authored_keys(snapshot),
                                                m_persistence.document().setup_intent(
                                                    m_persistence.document().active_conversation_id()))}}
                      .dump());
}
{
    if (m_web_view)
        m_web_view->host().start_turn();
}

void PrinterPanel::session_changed()
{
    if (!m_web_view)
        return;
    // A change to the printer is also a change to what the model is told
    // about it.
    m_web_view->host().set_session_profile(m_conversation->profile());
    m_web_view->host().send_page_envelope(Agent::Protocol::kPrinterSession, m_conversation->state_json());
}

void PrinterPanel::profile_changed()
{
    if (m_web_view)
        m_web_view->host().set_session_profile(m_conversation->profile());
}

